// AgentFace — the agent card face (glyph · name + role pill · blurb), shared by a normal agent node and
// the top card of a pool's stack. Lifted out of TeamsCanvas.tsx, where it is a private function, because
// the `teams-canvas` RECORD already imports it as a separate module (`@/components/teams-agent-face`) and
// that module did not exist — so `teams-canvas`, and `teamspage` through it, resolved to nothing.
// Sibling of `teams-org-legend`, which was split out of the same file for the same reason.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";

/** The resolved display fields for one position — declared locally rather than imported from
 *  `lib/orgView`, so the record is self-standing (the same choice `teams-canvas` makes for its own
 *  `Position`/`Persona` shapes). */
export interface PositionDisplay { glyph: string; name: string; role?: string; blurb: string }

export function AgentFace({ d, isSel }: { d: PositionDisplay; isSel: boolean }) {
  return (
    <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "10px 12px",
      display: "flex", flexDirection: "column", gap: 8, borderRadius: 13, background: "var(--bg-elev)",
      border: `1px solid ${isSel ? "var(--accent)" : "var(--border)"}`,
      boxShadow: isSel ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)" : "0 3px 12px rgba(0,0,0,.3)" }}>
      <Row gap={9} align="start">
        <Box style={{ width: 27, height: 27, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 13, color: isSel ? "#fff" : "var(--accent)", background: isSel ? "var(--accent)" : "color-mix(in oklch, var(--accent) 14%, transparent)", flex: "none" }}>{d.glyph}</Box>
        <Box style={{ minWidth: 0, flex: 1 }}>
          <Row gap={6} align="center">
            <Text as="span" weight={600} size={13.5} style={{ lineHeight: 1.15, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{d.name}</Text>
            {d.role && <Chip color="var(--accent)" style={{ flex: "none" }}>{d.role}</Chip>}
          </Row>
          {/* Clamp the blurb to 4 lines (#3335) so a long persona description ellipsis-truncates inside the
              card instead of overflowing the node box; the full text stays in the inspector. */}
          <Text as="div" size={10.5} tone="muted" style={{ lineHeight: 1.3, marginTop: 2,
            display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{d.blurb}</Text>
        </Box>
      </Row>
    </Box>
  );
}
